"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["14655"],{262070(n){n.exports=JSON.parse('{"id":9580,"title":"DS\u5B98\u65B9\u63D0\u793A\u8BCD\u2014\u2014\u4EE3\u7801\u6539\u5199","description":"USER\\t\\n\u4E0B\u9762\u8FD9\u6BB5\u7684\u4EE3\u7801\u7684\u6548\u7387\u5F88\u4F4E\uFF0C\u4E14\u6CA1\u6709\u5904\u7406\u8FB9\u754C\u60C5\u51B5\u3002\u8BF7\u5148\u89E3\u91CA\u8FD9\u6BB5\u4EE3\u7801\u7684\u95EE\u9898\u4E0E\u89E3\u51B3\u65B9\u6CD5\uFF0C\u7136\u540E\u8FDB\u884C\u4F18\u5316\uFF1A\\n```\\ndef fib(n):\\n    if n <= 2:\\n        return n\\n    return fib(n-1) + fib(n-2)\\n```\\n\\n\u6837\u4F8B\u8F93\u51FA\\n### \u95EE\u9898\u5206\u6790\\n\\n\u8FD9\u6BB5\u4EE3\u7801\u5B9E\u73B0\u4E86\u4E00\u4E2A\u9012\u5F52\u7684\u6590\u6CE2\u90A3\u5951\u6570\u5217\u8BA1\u7B97\u51FD\u6570 `fib(n)`\u3002\u867D\u7136\u4EE3\u7801\u7B80\u6D01\uFF0C\u4F46\u5B83\u5B58\u5728\u4EE5\u4E0B\u51E0\u4E2A\u95EE\u9898\uFF1A\\n\\n1. **\u91CD\u590D\u8BA1\u7B97**\uFF1A\u9012\u5F52\u8C03\u7528\u4F1A\u5BFC\u81F4\u5927\u91CF\u7684\u91CD\u590D\u8BA1\u7B97\u3002\u4F8B\u5982\uFF0C\u8BA1\u7B97 `fib(5)` \u65F6\uFF0C`fib(3)` \u548C `fib(2)` \u4F1A\u88AB\u591A\u6B21\u8BA1\u7B97\uFF0C\u5BFC\u81F4\u6548\u7387\u4F4E\u4E0B\u3002\\n\\n2. **\u8FB9\u754C\u60C5\u51B5\u5904\u7406\u4E0D\u5B8C\u5584**\uFF1A\u867D\u7136\u4EE3\u7801\u4E2D\u5904\u7406\u4E86 `n <= 2` \u7684\u60C5\u51B5\uFF0C\u4F46\u6CA1\u6709\u5904\u7406 `n < 0` \u7684\u60C5\u51B5\u3002\u5BF9\u4E8E\u8D1F\u6570\u8F93\u5165\uFF0C\u51FD\u6570\u4F1A\u8FD4\u56DE\u4E0D\u6B63\u786E\u7684\u7ED3\u679C\u3002\\n\\n3. **\u9012\u5F52\u6DF1\u5EA6\u9650\u5236**\uFF1A\u5BF9\u4E8E\u8F83\u5927\u7684 `n`\uFF0C\u9012\u5F52\u6DF1\u5EA6\u53EF\u80FD\u4F1A\u8D85\u8FC7 Python \u7684\u9ED8\u8BA4\u9012\u5F52\u6DF1\u5EA6\u9650\u5236\uFF0C\u5BFC\u81F4 `RecursionError`\u3002\\n\\n### \u89E3\u51B3\u65B9\u6CD5\\n\\n1. **\u4F7F\u7528\u8BB0\u5FC6\u5316\uFF08Memoization\uFF09**\uFF1A\u901A\u8FC7\u7F13\u5B58\u5DF2\u7ECF\u8BA1\u7B97\u8FC7\u7684\u6590\u6CE2\u90A3\u5951\u6570\u5217\u503C\uFF0C\u907F\u514D\u91CD\u590D\u8BA1\u7B97\uFF0C\u63D0\u9AD8\u6548\u7387\u3002\\n\\n2. **\u5904\u7406\u8FB9\u754C\u60C5\u51B5**\uFF1A\u589E\u52A0\u5BF9 `n < 0` \u7684\u68C0\u67E5\uFF0C\u5E76\u8FD4\u56DE\u9002\u5F53\u7684\u9519\u8BEF\u4FE1\u606F\u6216\u9ED8\u8BA4\u503C\u3002\\n\\n3. **\u4F7F\u7528\u8FED\u4EE3\u4EE3\u66FF\u9012\u5F52**\uFF1A\u9012\u5F52\u867D\u7136\u7B80\u6D01\uFF0C\u4F46\u5728\u5904\u7406\u5927\u89C4\u6A21\u6570\u636E\u65F6\u6548\u7387\u8F83\u4F4E\u3002\u53EF\u4EE5\u4F7F\u7528\u8FED\u4EE3\u65B9\u6CD5\u6765\u8BA1\u7B97\u6590\u6CE2\u90A3\u5951\u6570\u5217\uFF0C\u907F\u514D\u9012\u5F52\u6DF1\u5EA6\u9650\u5236\u3002\\n\\n### \u4F18\u5316\u540E\u7684\u4EE3\u7801\\n\\n#### \u65B9\u6CD5\u4E00\uFF1A\u8BB0\u5FC6\u5316\u9012\u5F52\\n\\n```python\\ndef fib(n, memo={}):\\n    if n < 0:\\n        raise ValueError(\\"Input must be a non-negative integer\\")\\n    if n <= 2:\\n        return 1\\n    if n in memo:\\n        return memo[n]\\n    memo[n] = fib(n-1, memo) + fib(n-2, memo)\\n    return memo[n]\\n```\\n\\n#### \u65B9\u6CD5\u4E8C\uFF1A\u8FED\u4EE3\u6CD5\\n\\n```python\\ndef fib(n):\\n    if n < 0:\\n        raise ValueError(\\"Input must be a non-negative integer\\")\\n    if n <= 2:\\n        return 1\\n    \\n    a, b = 1, 1\\n    for _ in range(3, n+1):\\n        a, b = b, a + b\\n    return b\\n```\\n\\n### \u89E3\u91CA\\n\\n1. **\u8BB0\u5FC6\u5316\u9012\u5F52**\uFF1A\\n   - \u4F7F\u7528\u4E00\u4E2A\u5B57\u5178 `memo` \u6765\u5B58\u50A8\u5DF2\u7ECF\u8BA1\u7B97\u8FC7\u7684\u6590\u6CE2\u90A3\u5951\u6570\u5217\u503C\u3002\\n   - \u5728\u6BCF\u6B21\u9012\u5F52\u8C03\u7528\u524D\uFF0C\u5148\u68C0\u67E5 `memo` \u4E2D\u662F\u5426\u5DF2\u7ECF\u6709\u7ED3\u679C\uFF0C\u5982\u679C\u6709\u5219\u76F4\u63A5\u8FD4\u56DE\uFF0C\u907F\u514D\u91CD\u590D\u8BA1\u7B97\u3002\\n   - \u5904\u7406\u4E86 `n < 0` \u7684\u60C5\u51B5\uFF0C\u629B\u51FA `ValueError`\u3002\\n\\n2. **\u8FED\u4EE3\u6CD5**\uFF1A\\n   - \u4F7F\u7528\u4E24\u4E2A\u53D8\u91CF `a` \u548C `b` \u6765\u4FDD\u5B58\u524D\u4E24\u4E2A\u6590\u6CE2\u90A3\u5951\u6570\u5217\u503C\u3002\\n   - \u901A\u8FC7\u5FAA\u73AF\u4ECE `3` \u5230 `n` \u8BA1\u7B97\u6590\u6CE2\u90A3\u5951\u6570\u5217\u503C\uFF0C\u907F\u514D\u4E86\u9012\u5F52\u8C03\u7528\uFF0C\u63D0\u9AD8\u4E86\u6548\u7387\u3002\\n   - \u540C\u6837\u5904\u7406\u4E86 `n < 0` \u7684\u60C5\u51B5\uFF0C\u629B\u51FA `ValueError`\u3002\\n\\n### \u603B\u7ED3\\n\\n\u4F18\u5316\u540E\u7684\u4EE3\u7801\u4E0D\u4EC5\u63D0\u9AD8\u4E86\u6548\u7387\uFF0C\u8FD8\u5B8C\u5584\u4E86\u8FB9\u754C\u60C5\u51B5\u7684\u5904\u7406\u3002\u8BB0\u5FC6\u5316\u9012\u5F52\u548C\u8FED\u4EE3\u6CD5\u90FD\u662F\u6709\u6548\u7684\u4F18\u5316\u624B\u6BB5\uFF0C\u5177\u4F53\u9009\u62E9\u54EA\u79CD\u65B9\u6CD5\u53D6\u51B3\u4E8E\u5177\u4F53\u9700\u6C42\u548C\u573A\u666F\u3002","remark":"\u5BF9\u4EE3\u7801\u8FDB\u884C\u4FEE\u6539\uFF0C\u6765\u5B9E\u73B0\u7EA0\u9519\u3001\u6CE8\u91CA\u3001\u8C03\u4F18\u7B49\u3002","notes":"\u63D0\u793A\u8BCD\u6765\u6E90https://api-docs.deepseek.com/zh-cn/prompt-library/","owner":"o0lirvyi0o","upvotes":2,"downvotes":0,"upvoteDifference":2,"updatedAt":"2026-04-13T20:38:56.155Z"}')}}]);